-- Backfill des form_submit perdus pendant la panne de l'automation Wix
-- (12/08/2026 16:06 UTC -> 21/08/2026 22:26 UTC). L'automation « Form
-- Submitted -> POST form-webhook » a été supprimée le 11/08 lors d'un
-- remaniement des automations ; recréée le 22/08. Source : export CSV Wix
-- officiel du 22/08 (824 soumissions), croisé avec l'API Wix Submissions.
-- Empreinte d'idempotence IDENTIQUE à scripts/wix_forms_import.py :
-- props->>'submission_id' = 'wiximport-'+sha1(date|email|tel|nom|prenom)[:20]
-- = crm_prospects.wix_submission_id (lien events<->crm materialisé).
-- Rows iso-format form-webhook v13 (_shared/form_row.ts), SANS PII,
-- capture_source='wix-backfill'. Aucun UPDATE, INSERT only, doublement
-- protégé (anti-join submission_id + anti-join temporel ±2 s).

-- 1. Matérialiser l'index unique de dédup (présent en prod depuis Sprint 25,
--    absent des migrations — drift repo/prod constaté le 22/08/2026).
CREATE UNIQUE INDEX IF NOT EXISTS events_form_submit_submission_id_uniq
  ON public.events ((props ->> 'submission_id'))
  WHERE name = 'form_submit' AND (props ->> 'submission_id') IS NOT NULL;

