INSERT INTO public.events
  (anonymous_id, session_id, name, url, path, hostname, title, referrer,
   referrer_hostname, utm_source, utm_medium, utm_campaign, utm_term,
   utm_content, user_agent, device_type, os, browser, viewport_width,
   viewport_height, country, props, occurred_at, received_at)
SELECT
  v.anonymous_id, v.session_id, 'form_submit', v.url, v.path, v.hostname,
  NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL,
  'Wix-Automation-Webhook', 'server', NULL, NULL, NULL, NULL, NULL,
  v.props, v.occurred_at, now()
FROM v
WHERE NOT EXISTS (
    SELECT 1 FROM public.events e
    WHERE e.name = 'form_submit'
      AND e.props ->> 'submission_id' = v.props ->> 'submission_id'
  )
  AND NOT EXISTS (
    SELECT 1 FROM public.events e
    WHERE e.name = 'form_submit'
      AND abs(extract(epoch FROM (e.occurred_at - v.occurred_at))) < 2
  );

-- 3. Annotation : les chiffres d'août 2026 sont restatés à la hausse.
INSERT INTO public.annotations (day, kind, label)
VALUES ('2026-08-23', 'autre',
  'Backfill de 22 form_submit (12-21/08) perdus par la suppression accidentelle de l''automation Wix -> webhook le 11/08. Les contacts macro d''août remontent rétroactivement (~+20). Un « avant/après 23/08 » sur les forms d''août n''est PAS un changement de comportement.');
